using Seqeron.Genomics.Emboss.SequenceFormats;

namespace Seqeron.Mcp.EmbossSequenceFormats.Tools;


// B09 WP61 (F280): the common part of the MCP tools of the EMBOSS sequence programs (AnalysisTools.EmbossSequencePrograms.cs, generated by scripts/docs/gen_emboss_wp61_tools.py).
public partial class EmbossSequenceFormatsTools
{
    private static void AddQualifierTokens(List<string> args, string? qualifiers)
    {
        if (!string.IsNullOrWhiteSpace(qualifiers))
            args.AddRange(qualifiers.Split([' ', '\t', '\r', '\n'], StringSplitOptions.RemoveEmptyEntries));
    }

    private static EmbossProgramToolResult RunEmbossSequenceProgram(string program, List<string> args, IReadOnlyDictionary<string, string> files, string outputFormat, string parameter, EmbossRunEnvironment? environment = null)
    {
        args.AddRange(["-outseq", "stdout"]);
        if (!string.IsNullOrWhiteSpace(outputFormat) && !string.Equals(outputFormat, "fasta", StringComparison.OrdinalIgnoreCase))
            args.AddRange(["-osformat", outputFormat]);
        try
        {
            var r = EmbossProgramRunner.Run(program, args, files, environment ?? new EmbossRunEnvironment());
            var messages = r.Stderr.Split('\n', StringSplitOptions.RemoveEmptyEntries);
            if (r.ExitCode != 0)
                throw new ArgumentException(string.Join("; ", messages), parameter);
            return new EmbossProgramToolResult(r.Stdout, new Dictionary<string, string>(r.Files), messages);
        }
        catch (Exception e) when (e is NotSupportedException or InvalidOperationException)
        {
            throw new ArgumentException(e.Message, parameter);
        }
    }

    private static EmbossProgramToolResult RunEmbossOutfileProgram(string program, List<string> args, IReadOnlyDictionary<string, string> files, string parameter, EmbossRunEnvironment? environment = null)
    {
        args.AddRange(["-outfile", "out.txt"]);
        try
        {
            var r = EmbossProgramRunner.Run(program, args, files, environment ?? new EmbossRunEnvironment());
            var messages = r.Stderr.Split('\n', StringSplitOptions.RemoveEmptyEntries);
            if (r.ExitCode != 0)
                throw new ArgumentException(string.Join("; ", messages), parameter);
            return new EmbossProgramToolResult(r.Files.TryGetValue("out.txt", out string? text) ? text : "", new Dictionary<string, string>(), messages);
        }
        catch (Exception e) when (e is NotSupportedException or InvalidOperationException)
        {
            throw new ArgumentException(e.Message, parameter);
        }
    }

    // B09 WP63 (F282): a program with several outputs: the text of the main output (a file, or the standard output when it is "stdout") and the other files the program wrote
    private static EmbossProgramToolResult RunEmbossMultiProgram(string program, List<string> args, IReadOnlyDictionary<string, string> files, string parameter, string main)
    {
        try
        {
            var r = EmbossProgramRunner.Run(program, args, files, new EmbossRunEnvironment());
            var messages = r.Stderr.Split('\n', StringSplitOptions.RemoveEmptyEntries);
            if (r.ExitCode != 0)
                throw new ArgumentException(string.Join("; ", messages), parameter);
            var others = r.Files.Where(f => f.Key != main).ToDictionary(f => f.Key, f => f.Value);
            string text = r.Stdout;
            if (main != "stdout")
                text = r.Files.TryGetValue(main, out string? t) ? t : "";
            return new EmbossProgramToolResult(text, others, messages);
        }
        catch (Exception e) when (e is NotSupportedException or InvalidOperationException)
        {
            throw new ArgumentException(e.Message, parameter);
        }
    }

    // the USA of the sequence input: the value given, else asis::TEXT, else the file the text is put in
    public static string SequenceSpec(string? sequenceValue, string sequence, string file)
    {
        if (!string.IsNullOrWhiteSpace(sequenceValue))
            return sequenceValue;
        return sequence.TrimStart().StartsWith("asis::", StringComparison.OrdinalIgnoreCase) ? sequence.Trim() : file;
    }
}
